 -- Arbeitsrecht Berufsbildung > Betriebswirtschaftliche Grundlagen > Finanzierungsarten > Eigenkapital
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wird bei der Finanzierung von IT-Hardware durch Eigenkapital das Eigentum sofort auf den Betrieb übertragen?', 2, '[{"text": "Ja", "correct": true, "because": "Eigenkapital finanziert den Kauf direkt"}, {"text": "Nein", "correct": false, "because": "Eigentum wird übertragen"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Finanzierung durch Eigenkapital für einen IT-Betrieb Zinsen gezahlt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Eigenkapital ist zinsfrei"}, {"text": "Ja", "correct": false, "because": "Zinsen fallen bei Fremdkapital an"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch Eigenkapitalfinanzierung die volle Kontrolle über Investitionen behalten?', 2, '[{"text": "Ja", "correct": true, "because": "Eigenkapital bedeutet keine Abhängigkeit von Gläubigern"}, {"text": "Nein", "correct": false, "because": "Kontrolle bleibt beim Betrieb"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist bei der Eigenkapitalfinanzierung von IT-Ausrüstung eine Rückzahlung erforderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Eigenkapital muss nicht zurückgezahlt werden"}, {"text": "Ja", "correct": false, "because": "Keine Rückzahlungspflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch Eigenkapitalfinanzierung Liquidität verlieren?', 2, '[{"text": "Ja", "correct": true, "because": "Eigenkapital bindet verfügbare Mittel"}, {"text": "Nein", "correct": false, "because": "Liquidität wird reduziert"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist ein wesentliches Merkmal der Eigenkapitalfinanzierung für einen IT-Betrieb?', 2, '[{"text": "Keine Zinskosten", "correct": true, "because": "Eigenkapital ist zinsfrei"}, {"text": "Rückzahlungspflicht", "correct": false, "because": "Keine Rückzahlung erforderlich"}, {"text": "Laufende Raten", "correct": false, "because": "Das gilt für Fremdkapital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten entstehen einem IT-Betrieb typischerweise bei der Eigenkapitalfinanzierung von Servern?', 3, '[{"text": "Einmalige Anschaffungskosten", "correct": true, "because": "Eigenkapital deckt die Anschaffung direkt"}, {"text": "Monatliche Zinsen", "correct": false, "because": "Keine Zinsen bei Eigenkapital"}, {"text": "Leasingraten", "correct": false, "because": "Das gilt für Leasing"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich für einen IT-Betrieb durch die Eigenkapitalfinanzierung von Software?', 3, '[{"text": "Keine finanziellen Verpflichtungen", "correct": true, "because": "Keine Rückzahlung oder Zinsen"}, {"text": "Geringere Anfangskosten", "correct": false, "because": "Volle Kosten werden sofort getragen"}, {"text": "Flexibilität bei Rückgabe", "correct": false, "because": "Keine Rückgabe bei Kauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Quelle wird bei der Eigenkapitalfinanzierung eines IT-Betriebs genutzt?', 2, '[{"text": "Eigene Rücklagen", "correct": true, "because": "Eigenkapital stammt aus eigenen Mitteln"}, {"text": "Bankkredit", "correct": false, "because": "Das ist Fremdkapital"}, {"text": "Leasingvertrag", "correct": false, "because": "Das ist eine andere Finanzierungsart"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nachteil der Eigenkapitalfinanzierung für einen IT-Betrieb?', 3, '[{"text": "Verlust von Liquidität", "correct": true, "because": "Eigenkapital bindet verfügbare Mittel"}, {"text": "Hohe Zinskosten", "correct": false, "because": "Keine Zinsen bei Eigenkapital"}, {"text": "Keine Kontrolle über Investitionen", "correct": false, "because": "Kontrolle bleibt erhalten"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat die Eigenkapitalfinanzierung für einen IT-Betrieb?', 4, '[{"text": "Keine Rückzahlungspflicht", "correct": true, "because": "Eigenkapital muss nicht zurückgezahlt werden"}, {"text": "Keine Zinskosten", "correct": true, "because": "Eigenkapital ist zinsfrei"}, {"text": "Hohe Anfangskosten", "correct": true, "because": "Volle Zahlung aus eigenen Mitteln"}, {"text": "Laufende Raten", "correct": false, "because": "Das gilt für Fremdkapital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Eigenkapitalfinanzierung von IT-Ausrüstung für einen IT-Betrieb?', 3, '[{"text": "Keine Zinsbelastung", "correct": true, "because": "Eigenkapital ist zinsfrei"}, {"text": "Volle Eigentumsübertragung", "correct": true, "because": "Kauf mit Eigenkapital"}, {"text": "Geringere Anfangskosten", "correct": false, "because": "Kosten werden sofort getragen"}, {"text": "Unabhängigkeit von Gläubigern", "correct": true, "because": "Keine Fremdfinanzierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die Eigenkapitalfinanzierung von Hardware für einen IT-Betrieb?', 4, '[{"text": "Hohe Anfangsinvestition", "correct": true, "because": "Volle Zahlung aus eigenen Mitteln"}, {"text": "Verlust von Liquidität", "correct": true, "because": "Eigenkapital bindet Mittel"}, {"text": "Zinskosten", "correct": false, "because": "Keine Zinsen bei Eigenkapital"}, {"text": "Kapitalbindung", "correct": true, "because": "Mittel sind gebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten entstehen bei der Eigenkapitalfinanzierung von Softwarelizenzen für einen IT-Betrieb?', 3, '[{"text": "Einmalige Anschaffungskosten", "correct": true, "because": "Eigenkapital deckt die Anschaffung"}, {"text": "Wartungskosten", "correct": true, "because": "Wartung kann zusätzlich anfallen"}, {"text": "Zinskosten", "correct": false, "because": "Keine Zinsen bei Eigenkapital"}, {"text": "Abschreibungen", "correct": true, "because": "Software wird abgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die Eigenkapitalfinanzierung von der Kreditfinanzierung für einen IT-Betrieb?', 3, '[{"text": "Keine Zinskosten bei Eigenkapital", "correct": true, "because": "Eigenkapital ist zinsfrei"}, {"text": "Keine Rückzahlung bei Eigenkapital", "correct": true, "because": "Eigenkapital muss nicht zurückgezahlt werden"}, {"text": "Geringere Anfangskosten bei Eigenkapital", "correct": false, "because": "Anfangskosten sind hoch"}, {"text": "Eigentumsübertragung bei beiden", "correct": true, "because": "Beide führen zum Eigentum"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eigenkapitalfinanzierung überträgt das Eigentum an Hardware. b) Eigenkapitalfinanzierung hat Zinskosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eigentum ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eigenkapitalfinanzierung schont die Liquidität nicht. b) Eigenkapitalfinanzierung erfordert keine Rückzahlung.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Liquidität wird gebunden, keine Rückzahlung"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Bei Eigenkapitalfinanzierung fallen Abschreibungen an. b) Eigenkapitalfinanzierung ist immer günstiger als Kredit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abschreibungen ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eigenkapitalfinanzierung bietet Unabhängigkeit von Gläubigern. b) Eigenkapitalfinanzierung hat geringere Anfangskosten als Kauf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unabhängigkeit ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eigenkapitalfinanzierung bindet Liquidität. b) Eigenkapitalfinanzierung erfordert Zinszahlungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Liquidität ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

